final class QuantResearchChecks {
 static int count;
 interface Throwing{void run()throws Exception;}
 static void check(boolean ok,String why){count++;if(!ok)throw new AssertionError(why);}
 static void rejects(Throwing fn,String why)throws Exception{boolean failed=false;try{fn.run();}catch(Exception e){failed=true;}check(failed,why);}
 static void same(Object a,Object b,String path)throws Exception{
  if(a instanceof JSONObject&&b instanceof JSONObject){JSONObject x=(JSONObject)a,y=(JSONObject)b;check(x.length()==y.length(),"keys "+path);for(Iterator<String>it=x.keys();it.hasNext();){String k=it.next();check(y.has(k),"key "+path+"."+k);same(x.get(k),y.get(k),path+"."+k);}return;}
  if(a instanceof JSONArray&&b instanceof JSONArray){JSONArray x=(JSONArray)a,y=(JSONArray)b;check(x.length()==y.length(),"length "+path);for(int i=0;i<x.length();i++)same(x.get(i),y.get(i),path+"["+i+"]");return;}
  if(a instanceof Number&&b instanceof Number){double x=((Number)a).doubleValue(),y=((Number)b).doubleValue();check(Math.abs(x-y)<=1e-10*Math.max(1,Math.max(Math.abs(x),Math.abs(y))),"number "+path);return;}
  check(Objects.equals(a,b),"value "+path);
 }
 static void model(JSONObject fixture)throws Exception{
  JSONObject imported=QuantResearchModel.importText(fixture.getString("rawDataset"));same(imported,fixture.getJSONObject("record"),"raw import");JSONArray cases=fixture.getJSONArray("cases");for(int i=0;i<cases.length();i++){JSONObject sample=cases.getJSONObject(i),c=sample.getJSONObject("config");JSONObject result=QuantResearchModel.run(imported,c,new JSONArray(),()->false,null);same(result,sample.getJSONObject("result"),"family "+i);List<QuantResearchModel.Bar>bars=QuantResearchModel.readBars(fixture.getJSONObject("dataset")).get("600000");QuantResearchModel.Signal[]signals=QuantResearchModel.signals(bars,c.getString("family"),c.getJSONArray("parameters").getJSONObject(0).getJSONObject("settings"),()->false);JSONArray expected=sample.getJSONArray("signals");for(int j=0;j<signals.length;j++)check(signals[j].buy==expected.getJSONObject(j).getBoolean("buy")&&signals[j].sell==expected.getJSONObject(j).getBoolean("sell"),"signal "+i+"."+j);}
  JSONObject bad=new JSONObject(fixture.getJSONObject("dataset").toString());bad.getJSONArray("bars").put(bad.getJSONArray("bars").get(0));rejects(()->QuantResearchModel.importText(bad.toString()),"duplicate bars");JSONObject future=new JSONObject(fixture.getJSONObject("dataset").toString()).put("asOf","2025-01-01");rejects(()->QuantResearchModel.importText(future.toString()),"future bars");JSONObject nullVolume=new JSONObject(fixture.getJSONObject("dataset").toString());nullVolume.getJSONArray("bars").getJSONObject(0).put("volume",JSONObject.NULL);rejects(()->QuantResearchModel.importText(nullVolume.toString()),"unknown volume");JSONObject overlap=new JSONObject(fixture.getJSONArray("cases").getJSONObject(0).getJSONObject("config").toString()).put("stepDays",20);rejects(()->QuantResearchModel.validateConfig(overlap),"overlap");rejects(()->QuantResearchModel.run(imported,fixture.getJSONObject("edgeConfig"),new JSONArray(),()->true,null),"cancellation");
  JSONObject edgeData=new JSONObject(fixture.getJSONObject("dataset").toString()).put("bars",fixture.getJSONArray("edgeBars"));TreeMap<String,List<QuantResearchModel.Bar>>edgeBars=QuantResearchModel.readBars(edgeData);JSONArray edgeExpected=fixture.getJSONArray("edgeSignals");QuantResearchModel.Signal[]edgeSignals=new QuantResearchModel.Signal[edgeExpected.length()];for(int i=0;i<edgeSignals.length;i++)edgeSignals[i]=new QuantResearchModel.Signal(edgeExpected.getJSONObject(i).getBoolean("buy"),edgeExpected.getJSONObject(i).getBoolean("sell"));Map<String,QuantResearchModel.Signal[]>sig=new TreeMap<>();sig.put("600000",edgeSignals);List<QuantResearchModel.Bar>eb=edgeBars.get("600000");JSONObject edge=QuantResearchModel.simulate(edgeBars,sig,eb.get(1).date,eb.get(eb.size()-1).date,fixture.getJSONObject("edgeConfig"),()->false,true);same(edge,fixture.getJSONObject("edgeResult"),"execution edge");JSONObject archive=fixture.getJSONObject("largeArchive");same(QuantResearchModel.importText(archive.getString("rawUtf8")),archive,"large full archive");PersonMethodModel.validateVersion(fixture.getJSONObject("material"));
 }
 static void cleanup(QuantResearchStore s){for(String suffix:new String[]{"",".bak",".new",".lock",".view",".view.bak",".view.new",".view.lock"})new File(s.filePath()+suffix).delete();}
 static String run(Context c,String text)throws Exception{count=0;JSONObject fixture=new JSONObject(text);model(fixture);QuantResearchStore store=new QuantResearchStore(c,"quant-focused-"+UUID.randomUUID()+".json");try{check(!store.filePath().exists(),"empty open no write");JSONObject empty=store.read(),record=fixture.getJSONObject("record");store.merge(record,empty);rejects(()->store.merge(record,empty),"stale preview");same(store.get(record.getString("id")),record,"atomic dataset");QuantResearchStore reopened=new QuantResearchStore(c,store.filePath().getName());same(reopened.read(),store.read(),"reopen");JSONObject archive=fixture.getJSONObject("largeArchive");store.merge(archive,store.read());same(store.get(archive.getString("id")),archive,"large archive");JSONObject view=new JSONObject().put("schema","quant-native-view/v1").put("unknown",fixture.getJSONObject("material"));store.saveView(view,new JSONObject());rejects(()->store.saveView(view,new JSONObject()),"stale view");same(store.loadView(),view,"large view reopen");JSONObject job=QuantResearchModel.object("kind","run","id","job-test","status","queued","datasetId",record.getString("id"),"config",fixture.getJSONObject("edgeConfig"),"materials",new JSONArray().put(fixture.getJSONObject("material")));store.put(job,new JSONObject());JSONObject next=new JSONObject(job.toString()).put("status","failed").put("error","retained failure");store.put(next,job);rejects(()->store.put(job,job),"stale job");JSONObject changed=new JSONObject(next.toString());changed.getJSONObject("config").put("commissionBps",3);rejects(()->store.put(changed,next),"frozen config");same(store.get("job-test").getJSONArray("materials"),job.getJSONArray("materials"),"full frozen materials");return "QuantResearch Android store/model PASS "+count;}finally{cleanup(store);}}
 private static Button button(View v,String name){if(v instanceof Button&&name.equals(((Button)v).getText().toString()))return (Button)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){Button b=button(g.getChildAt(i),name);if(b!=null)return b;}}return null;}
 static String runGeometry(Context c,String text)throws Exception{count=0;JSONObject fixture=new JSONObject(text);QuantResearchStore store=new QuantResearchStore(c,"quant-geometry-"+UUID.randomUUID()+".json");try{QuantResearchScreen screen=new QuantResearchScreen(c,store,JSONArray::new,r->{});screen.previewImport(fixture.getJSONObject("largeArchive").getString("rawUtf8"));float density=c.getResources().getDisplayMetrics().density;int width=Math.round(900*density),height=Math.round(180*density);screen.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height,View.MeasureSpec.EXACTLY));screen.layout(0,0,width,height);View viewport=screen.findViewWithTag("quantViewport"),toolbar=screen.findViewWithTag("quantToolbar");check(viewport.getMeasuredHeight()>=Math.round(90*density),"short-wide reader >=90dp within180dp module");check(toolbar.getMeasuredHeight()>=Math.round(48*density),"toolbar touch row48dp");check(screen.findViewWithTag("quantDisclosure").getVisibility()==View.GONE,"short-wide disclaimer collapsed");check(((TextView)screen.findViewWithTag("quantStatus")).getMaxLines()==1,"short-wide status single line");Button explanation=button(screen,"说明 / 状态");check(explanation!=null&&explanation.getMeasuredHeight()>=Math.round(48*density),"full explanation reachable by48dp action");check(((ScrollView)viewport).canScrollVertically(1),"full text still scrollable");check(store.loadView().getJSONObject("pending").length()>0,"geometry retains pending preview");screen.setDarkTheme(true);width=Math.round(390*density);height=Math.round(780*density);screen.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height,View.MeasureSpec.EXACTLY));screen.layout(0,0,width,height);check(viewport.getMeasuredHeight()>=Math.round(550*density),"portrait reading area retained");return "QuantResearch Android geometry PASS "+count;}finally{cleanup(store);}}
 static String runScreen(Context c,String text)throws Exception{count=0;JSONObject fixture=new JSONObject(text);QuantResearchStore store=new QuantResearchStore(c,"quant-screen-"+UUID.randomUUID()+".json");try{JSONObject material=fixture.getJSONObject("material");QuantResearchScreen screen=new QuantResearchScreen(c,store,()->new JSONArray().put(material),r->{});button(screen,"刷新材料").performClick();button(screen,"冻结关联").performClick();screen.previewImport(fixture.getJSONObject("largeArchive").getString("rawUtf8"));check(store.read().getJSONArray("records").length()==0,"preview no writes");Bundle saved=screen.saveState();check(saved.size()==2&&!saved.containsKey("quantResearchState"),"small marker bundle");Parcel parcel=Parcel.obtain();saved.writeToParcel(parcel,0);check(parcel.dataSize()<4096,"binder bound with 700k text");parcel.recycle();JSONObject state=store.loadView();check(state.getInt("mode")==2&&state.getJSONObject("pending").length()>0,"sidecar pending mode");same(state.getJSONArray("materials").get(0),material,"large complete material");QuantResearchScreen restored=new QuantResearchScreen(c,store,()->new JSONArray().put(material),r->{});restored.restoreState(saved);JSONObject restoredState=store.loadView();same(restoredState,state,"rotation full preview");restored.confirmImport();check(store.read().getJSONArray("records").length()==1&&store.loadView().getJSONObject("pending").length()==0,"confirmed clears preview");restored.setDarkTheme(true);check(restored.back(),"results back to config");return "QuantResearch Android screen PASS "+count;}finally{cleanup(store);}}
 static void imports(JSONObject fixture,String bridgePath)throws Exception{rejects(()->QuantResearchModel.importText("{\"schema\":\"webstock.quant.result.v1\"} trailing"),"trailing JSON");rejects(()->QuantResearchModel.importText("{schema:'webstock.quant.result.v1'}"),"strict quoted JSON");JSONObject record=QuantResearchModel.importText(fixture.getString("rawDataset"));same(record,fixture.getJSONObject("record"),"strict import");JSONObject mismatch=QuantResearchModel.object("kind","run","id","mismatch","status","completed","datasetId",record.getString("id"),"config",fixture.getJSONObject("edgeConfig"),"materials",new JSONArray(),"result",new JSONObject().put("status","completed"));rejects(()->QuantResearchStore.validateRecord(mismatch),"completed frozen result");JSONObject packageRecord=QuantResearchModel.importText(new String(Files.readAllBytes(Paths.get(bridgePath)),StandardCharsets.UTF_8));check(packageRecord.getJSONObject("original").has("legacyDatasetEvidence"),"embedded actual legacy evidence");JSONObject bad=new JSONObject(packageRecord.getJSONObject("original").toString());bad.getJSONObject("legacyDatasetEvidence").getJSONArray("artifacts").getJSONObject(0).put("bytesBase64","ZmFrZQ==");rejects(()->QuantResearchModel.importText(bad.toString()),"embedded bytes tamper");}
 public static void main(String[]args)throws Exception{count=0;if(args[0].equals("--imports")){imports(new JSONObject(new String(Files.readAllBytes(Paths.get(args[1])),StandardCharsets.UTF_8)),args[2]);System.out.println("QuantResearch Java affected import checks PASS "+count);return;}String text=new String(Files.readAllBytes(Paths.get(args[0])),StandardCharsets.UTF_8);model(new JSONObject(text));if(args.length>1)Files.write(Paths.get(args[1]),text.getBytes(StandardCharsets.UTF_8));System.out.println("QuantResearch Java model/cross PASS "+count);}
}
